export const blurbs: Record<string, string> = {
 "f-wd160071": "Девушка влюбляется в таинственного одноклассника и попадает в сверхъестественный мир, наполненный враждой между вампирскими кланами.",
 "f-wd25136484": "Когда в городке Дерри, начинают пропадать дети, несколько ребят сталкиваются со своими величайшими страхами и вынуждены помериться силами со злобным клоуном Пеннивайзом, чьи проявления жестокости и список жертв уходят в глубь веков.",
 "f-wd60829653": "Эгоистичный «мажор» Гриша в один не очень прекрасный день после аварии приходит в себя... в 1860 году в барской усадьбе. Теперь он — обычный холоп без связей и связи: о смартфонах здесь не слышали, а все вокруг него — крепостные. Грише предстоит пройти непростой путь, чтобы из наглого сынка богатых родителей превратиться в человека, который умеет ценить простые вещи, умеет дружить, ну и, конечно, любить.",
 "f-wd15140437": "Когда Джон Коннор, лидер сопротивления, посылает сержанта Кайла Риза назад в 1984 год, чтобы защитить Сару Коннор и спасти будущее, неожиданный поворот событий создает разлом во времени. Сержант Риз оказывается в новой, незнакомой версии прошлого, где он встречает неожиданных союзников, в том числе Терминатора, новых опасных врагов, и новую миссию: изменить будущее...",
 "f-wd27985819": "После битвы с Таносом и возвращения всех исчезнувших после щелчка, Питер пытается вернуться к обычной жизни. Мир переживает последствия грандиозной битвы, а сам Питер тяжело переживает гибель Тони Старка, который стал для него наставником и близким человеком. Чтобы немного отвлечься от супергеройской жизни, Питер отправляется вместе с одноклассниками в школьную поездку по Европе. Однако путешествие неожиданно прерывается, когда появляется загадочный супергерой Мистерио и просит Человека-паука помочь остановить опасных существ, угрожающих миру.",
 "f-wd126796": "Испокон веков мифы и легенды окутывают загадочной пеленой живописные отроги Шотландских гор. Искусной лучнице Мериде приходится выбирать свой путь в жизни самостоятельно, и однажды она отказывается следовать древним традициям королевства, бросая вызов могущественным шотландским кланам и их предводителям: нескладному лорду МакГаффину, угрюмому лорду Макинтошу и сварливому лорду Дингволлу. Неосторожные поступки Мериды грозят повергнуть королевство в хаос, и тогда она отправляется за советом к эксцентричной отшельнице, которая вместо помощи накладывает на Мериду опасное заклятье. Юной принцессе предстоит полагаться только на собственную храбрость, чтобы преодолеть могущественное волшебство и победить самого страшного зверя из тех, что водятся в горных долинах.",
 "f-wd4254026": "Питер Паркер продолжает защищать Нью-Йорк в образе Человека-паука, одновременно пытаясь сохранить отношения с Гвен Стейси и сдержать обещание, данное её отцу. Вскоре он сталкивается сразу с несколькими опасными противниками, включая Электро — бывшего инженера, получившего невероятные способности после несчастного случая, — и своего старого друга Гарри Озборна, который отчаянно ищет способ спасти собственную жизнь. Пока угрозы становятся всё серьёзнее, Питеру приходится сделать выбор между личным счастьем и долгом героя.",
 "f-wd126487478": "Однажды ночью в небольшом городке 17 младшеклассников одновременно убежали из дома и бесследно исчезли. Все они учились в одном классе, и кроме них не пропал только один мальчик. Уже месяц полиция не может найти никаких зацепок, а безутешные родители считают, что с этим как-то связана новая классная руководительница.",
 "f-wd125726790": "Люси, лучшая сотрудница нью-йоркского брачного агентства, мастерски составляет пары, но сама ни с кем не встречается в уверенности, что выйдет замуж только за очень богатого. Однажды на свадьбе клиентов Люси знакомится с братом жениха, мужчиной во всех отношениях приятным и к тому же миллионером, и в этот самый момент в её жизнь возвращается бывший парень — актёр-неудачник, которого она бросила из-за проблем с деньгами.",
 "f-wd101112656": "1947-ой год. Венгерский архитектор Ласло Тот и его супруга Эржебет переезжают из послевоенной Европы в США. Там их жизнь стремительно меняется после знакомства с загадочным клиентом.",
 "f-wd4347438": "Хотя бы один взрослый, которого можно называть на «ты», должен быть в жизни каждого пацана… Актеры экстракласса — Валерий Приемыхов и тринадцатилетний Андрей Зыков — и ведущая тема фильмов Динары Асановой: непонимание, бесправие и одиночество подростка, против которого — весь мир взрослых.",
 "f-wd100361125": "Постапокалиптический боевик австралийского режиссёра Джорджа Миллера, приквел фильма «Безумный Макс: Дорога ярости».  Фильм посвящён истории главной героини картины «Безумный Макс: Дорога ярости» — Фуриосы",
 "f-wd124378349": "После кораблекрушения, умный робот по имени Роз оказывается на необитаемом острове. Чтобы выжить в суровых условиях, Роз налаживает связь с животными острова и заботится об одиноком гусенке-сироте.",
 "f-wd129906152": "Четверть века проработав в бумажной промышленности, Ю Ман-су стал высококлассным специалистом. Он выкупил и отремонтировал принадлежавший отцу загородный дом и считает себя счастливым семьянином и состоявшимся человеком, поэтому сильным шоком для мужчины становится внезапное увольнение. За несколько месяцев так и не найдя работу по специальности, Ман-су сталкивается с перспективой потери дома и от отчаяния решает физически устранить конкурентов на должность в компании мечты — таких же безработных бедолаг с блестящими резюме.",
 "f-wd115766625": "Месть одного человека приобретает национальные масштабы после того, как выясняется, что он является бывшим оперативником мощной и подпольной организации, известной как \"Пчеловоды\".",
 "f-wd56307503": "Конг и группа учёных отправляются в опасное путешествие в поисках родного дома гиганта. Среди них девочка Джия, единственная, кто умеет общаться с Конгом. Неожиданно они сталкиваются с разъярённым Годзиллой, разрушающим всё на своём пути. Битва двух титанов, спровоцированная неведомыми силами — лишь малая часть тайны, спрятанной в недрах Земли.",
 "f-wd55438657": "К 20 годам у него есть все, о чем только можно мечтать: талант, деньги, слава, любовь. Он — Эдуард Стрельцов, восходящая звезда советского футбола и кумир миллионов. Вся страна с замиранием сердца ждет побед советской сборной на предстоящем Чемпионате мира в Швеции и дуэли Стрельцова с Пеле. Но за два дня до отъезда команды недоброжелатели ломают судьбу спортсмена. Когда дорога в футбол, казалось бы, навсегда отрезана, Стрельцов должен совершить невозможное, чтобы вернуться и доказать всем, что он — чемпион. Великий спортсмен, заслуживший настоящую народную любовь.",
 "f-wd23006268": "Что если в один прекрасный день в тебя вселяется существо-симбиот, которое наделяет тебя сверхчеловеческими способностями? Вот только Веном – симбиот совсем недобрый, и договориться с ним невозможно. Хотя нужно ли договариваться?.. Ведь в какой-то момент ты понимаешь, что быть плохим вовсе не так уж и плохо. Так даже веселее. В мире и так слишком много супергероев! Мы – Веном!",
 "f-wd27689100": "Путешествие на одном из самых роскошных поездов Европы неожиданно превращается в одну из самых стильных и захватывающих загадок в истории. Фильм рассказывает историю тринадцати пассажиров поезда, каждый из которых находится под подозрением. И только сыщик должен как можно быстрее разгадать головоломку, прежде чем преступник нанесет новый удар.",
 "f-wd20926273": "2700 год. Валериан и Лорелин - космические спецагенты, которые по долгу службы впутались в подозрительное дело и стали невольными участниками то ли межгалактического заговора, то ли аферы причудливых поселенцев планеты Альфа, прибывших туда из различных миров со всех уголков галактик.",
 "f-wd26213906": "В этот новый год любимые герои «Ёлок» всё также делают глупости и надеются на чудо. Боре нужно как-то восстановить семейное счастье и ради этого он готов украсть у лучшего друга Жени пингвина. Лыжник и Сноубордист, так и не повзрослевшие, устраивают сумасшедшую погоню за ёлкой. Баба Маня осваивает интернет в надежде найти старую любовь. Профессор из Екатеринбурга остепенился, но теперь сам сходит с ума от ревности. На далеком Севере инженер по технике безопасности должен рискнуть и, наконец, признаться в любви. Ну а пингвину просто очень нужно сесть на яйцо…",
 "f-wd209538": "Когда мир Старка рушится на его глазах по вине неизвестных противников, Тони жаждет найти виновных и свести с ними счеты. Оказавшись в безвыходной ситуации, Старк может рассчитывать только на себя и свою изобретательность, чтобы защитить тех, кто ему дорог. Это становится настоящим испытанием для героя, которому придется не только сражаться с коварным врагом, но и разобраться в себе, чтобы найти ответ на вопрос, который давно его тревожит: что важнее — человек или костюм?",
 "f-wd12125299": "Юпитер Джонс родилась под ночным небом, и все знаки предсказывали, что девочке предстоят великие свершения. Юпитер выросла и каждый день видит во сне звезды, но просыпается в жесткой реальности, где она работает уборщицей и моет туалеты. Личная жизнь Юпитер тоже оставляет желать лучшего, пока девушка не встречает Кейна. Кейн, бывший военный охотник, прибывает на Землю, чтобы отыскать Юпитер и раскрыть девушке ее истинное предназначение. Благодаря своим генетическим особенностям Юпитер становится претенденткой невероятного наследия, способного изменить равновесие во Вселенной.",
 "f-wd28811584": "Ветеран Крестового похода лорд Робин Локсли возвращается в родной город Ноттингем и видит, что он погряз в коррупции. Робин присоединяется к группе Весёлых Шервудских Разбойников и становится знаменитым благородным вором, продолжая при этом вести светскую жизнь для слежки за ноттингемским шерифом.",
 "f-wd136163067": "Безнадёжный романтик Беар давно и безответно влюблён в красавицу Ники. Однажды в магазине эзотерики он находит странную безделушку — волшебную палочку. Если её сломать, исполнится твоё заветное желание. Беар загадывает, чтобы Ники любила его больше всех на свете. И девушка правда в него влюбляется. Однако его счастью быстро приходит конец. Парень замечает, что Ники буквально им одержима, а её знаки внимания становятся всё более пугающими. Оказывается, желание парня исполнилось, но совсем не так, как он мечтал.",
 "f-wd113877606": "Головной отдел мозга Райли внезапно подвергается капитальному ремонту в тот момент, когда необходимо освободить место для чего-то совершенно неожиданного: новых эмоций.  Радость, Печаль, Гнев, Страх и Брезгливость, которые уже давно успешно руководят эмоциональными процессами, не знают, что и чувствовать, когда появляется некая… Тревожность. И похоже, не только она.",
 "f-wd135685436": "Август 1944 года. Глухие леса Западной Белоруссии. Средиземье, недавно освобожденная территория — особая зона, где действуют оставленные в советском тылу вражеские разведывательно- диверсионные группы. Советские войска переходят государственную границу, война поворачивает вспять. Помешать этому может удар в спину наступающей армии. Предотвратить нападение могут только контрразведчики СМЕРШ.",
 "f-wd119998666": "Став жертвой коварного заговора, молодой Эдмон Дантес был арестован в день своей свадьбы за преступление, которое он не совершал. После 14 лет в тюрьме Замка Иф ему наконец-то удается бежать. На таинственном острове, о котором ему поведал в заключении его друг аббат Фариа, Эдмон находит легендарное сокровище и становится графом Монте- Кристо. Теперь его единственная цель — месть.",
 "f-wd40083273": "Четыре неудачника — Гарретт «Мусорщик» Гаррисон, Генри, Натали и Дон, сталкиваются с обычными проблемами, когда их внезапно затягивает через таинственный портал в Верхний мир: странную кубическую страну чудес, которая процветает благодаря воображению. Чтобы вернуться домой, им придётся освоить этот мир, отправляясь в магическое путешествие с неожиданным экспертом-ремесленником Стивом. Это приключение бросит вызов всем пятерым, заставит их проявить смелость и восстановить качества, которые делают каждого из них уникальным творческим человеком.",
 "f-wd248775": "В недалёком будущем после крупной катастрофы вся жизнь сосредоточилась вдоль бесчисленных магистралей. Банда байкеров, желая рассчитаться за убитого товарища, преследует молодого полицейского Макса. Жертвой их мести становится лучший друг Макса, и теперь эта же участь грозит самому Максу и его семье.",
 "f-wd300552": "Милош — бывший известный порноактер, ныне отошедший от дел и живущий тихой семейной жизнью. У него есть любимая и любящая жена и маленький сын. Мирную жизнь внезапно нарушает встреча с бывшей коллегой Лейлой — порноактрисой, которая предлагает Милошу в последний раз сняться в порно у некоего Вукмира. Милош знакомится с Вукмиром — эксцентричным богатым человеком, снимающим некое особое, эксклюзивное порно на заказ. Он предлагает Милошу сумму, которой хватит на безбедное существование ему с женой и его сыну на всю жизнь. Поначалу Милош отказывается, но, обсудив все с женой, даёт согласие. Вукмир в восторге, и даёт ему инструкции о том, как приготовиться к съёмкам. При этом рядом с Милошем начинают все время пребывать охранники Вукмира, а также приставленный к Милошу личный шофер. Милош активно готовится к съёмкам, возвращая себе былую форму. Настает день съёмок, которые проходят в совершенно особых условиях: шофер привозит его в некое здание, охранники на время превращаются в операторов.",
 "f-wd124651039": "В жестокой системе камер, расположенных по вертикали, таинственный лидер устанавливает свой закон. Новая заключенная борется с сомнительным методом распределения пищи.",
 "f-wd125622191": "Чем занять себя на пенсии? Джойс, Элизабет, Рон и Ибрагим, живущие в доме для престарелых, решили организовать детективный кружок. Каждый четверг они собираются для того, чтобы поломать голову над одним из нераскрытых полицией дел. Все это не более, чем игра и повод размять мозги, но однажды друзья сталкиваются с настоящим преступлением. Теперь у них появляется шанс доказать, что еще есть порох в пороховницах, и помочь полиции. Получится ли у детективов-любителей найти преступника?",
 "f-wd134430": "Принцесса Белоснежка в раннем детстве потеряла мать, а её отец-король женился вновь. Тщеславная и злобная Королева, завидуя красоте юной падчерицы, вынуждает девочку ходить в лохмотьях и делать чёрную работу, помыкает ею как служанкой. Узнав от волшебного зеркальца, что Белоснежка стала самой прекрасной девушкой на свете, завистница решила погубить прелестную падчерицу. Но бедная девушка не погибла в лесу, а наоборот, встретила там настоящих друзей — забавных семерых гномов: Профессора, Ворчуна, Весельчака, Скромника, Чихоню, Соню и Молчуна.",
 "f-wd179673": "Фильм приглашает в зачарованный замок, скрытый в чаще темного волшебного леса. Его хозяин ужасное Чудовище, которого все боятся и ненавидят. Лишь самая прекрасная и смелая девушка в мире по имени Белль способна разгадать тайну страшного, а на самом деле, очень несчастного хозяина замка и разрушить чары, обрекшие его на вечное пребывание в шкуре жуткого зверя.Только тот, кто растопит лед в сердце чудовища и сможет полюбить его таким, какой он есть, сможет вернуть ему человеческий облик, но, чтобы спасти хозяина зачарованного замка, Белль придется выступить против всех: ведь жители ее деревни, подстрекаемые злобным охотником Гастоном, хотят погубить гордое и доброе Чудовище…",
 "f-wd4341553": "Волшебная звёздная ночь... Гепетто хочет достать самую яркую волшебную звезду с неба. Его единственное желание - создать деревянного человечка Пиноккио, который бы превратился в настоящего мальчика и стал его сыном, которого у него никогда не было. Той ночью, красивая Синяя Фея коснулась Пиноккио своей волшебной палочкой, и он ожил. Сбылась самая заветная мечта Гепетто. Хотя Пиноккио и ожил, Фея сообщает ему о том, что он сможет стать настоящим, если докажет, что он храбрый, правдивый и бескорыстный. Благодаря умному сверчку Джимини Крикет, Пиноккио учится различать, что правильно, а что нет. Пиноккио отправляется в школу... Вот тут-то и начинаются невероятные приключения...",
 "f-wd205028": "Прошло полгода с тех пор, как мир узнал, что миллиардер-изобретатель Тони Старк является обладателем уникальной кибер-брони Железного человека. Общественность требует, чтобы Старк передал технологию брони правительству США, но Тони не хочет разглашать её секреты, потому что боится, что она попадёт не в те руки. Между тем, Иван Ванко — сын русского учёного когда-то работавшего на фирму Старка, но потом уволенного и лишенного всего, намерен отомстить Тони за беды своей семьи. Для чего сооружает своё высокотехнологичное оружие.",
 "f-wd63026": "Вторая мировая война близится к концу. Молодая канадская медсестра ухаживает на заброшеной вилле за своим «английским пациентом», который получил страшные ожоги во время авиакатастрофы в пустыне Сахара. Медленно угасая, он воскрешает в памяти свой страстный роман с замужней женщиной, сметенный ураганом войны и банальными предрассудками, что в конце концов и привело к трагической развязке.",
 "f-wd756238": "Действие фильма разворачивается в мире, населённом исключительно роботами. Как и в мире людей у них есть своя социальная лестница, свои герои и изгои. Молодой гений Родни мечтает сделать мир роботов лучше. А ещё ему очень нравится одна молоденькая сексапильная роботша Каппи. Но на пути всех его планов стоит ведущий дизайнер роботов Биг Велд, принадлежащий к тому же сословию, что и Каппи...",
 "f-wd193835": "Уилл Хантинг - 20-летний вундеркинд из Бостона, который то и дело ввязывается в неприятные истории. И когда полиция арестовывает его за очередную драку, профессор математики берет его под свою опеку, но при одном условии: Уилл должен пройти курс психотерапии. Сеансы «перевоспитания», начавшиеся с недоверия, постепенно перерастают в дружбу между Уиллом и его наставником.",
 "f-wd76479": "Фильм является вольным римейком самурайской драмы Акиры Куросавы «Телохранитель» (1961), действие которого перенесено на границу США и Мексики. В небольшой пограничный городок Сан-Мигель приезжает бродяга-стрелок (Клинт Иствуд). Жителей на улицах нет, первый, кого он встречает — усаженный на лошадь мертвец, к спине которого приколота издевательская записка «Adios, amigo» («Прощай, друг»). Со слов хозяина салуна стрелок узнаёт, что городок стал ареной противоборства двух банд, которые занимаются контрабандой — мексиканцев Рохо и американцев Бакстеров. Обе банды равно сильны, и ни одна не может взять верх над другой...",
 "f-wd116852": "Извечное противостояние добра и зла: сумасшедший, но обаятельный злодей Джокер — смертельная угроза для города Готэма. Бескомпромиссный и загадочный Бэтмен — его последняя надежда на спасение. Только герой-спаситель не желает раскрывать своё подлинное имя, и не только из скромности... Но настойчивая журналистка полна решимости узнать, кому жители Готэма обязаны всем...",
 "f-wd209170": "Семейство Бенкс озабоченно поисками няни для своих детей. И как это бывает только в сказке, она появилась прямо из воздуха, прекрасная, ни на кого не похожая. Как раз такая, какую мечтали бы иметь в своем доме всякие любящие родители. У неё не просто цветущий вид. Она не просто лучше всех умеет готовить, ходить по магазинам, одеваться, танцевать и воспитывать детей. Это всё лишь элементы, лишь составляющие. Нет, тут нечто большее — она именно совершенна, именно лишена недостатков, ибо она — сказочная. Как же не влюбиться в такую…",
 "f-wd212145": "Ренард, техногенный террорист, обладает необыкновенной, смертельно опасной способностью - он не чувствует боли. Способность эта возникла у него в результате пулевого ранения в голову. Когда Ренард изобретает хитроумную схему, позволяющую взять под контроль все нефтяные ресурсы планеты, Агент 007 становится последней надеждой человечества. Миссия сулит ему как опасности, так и удовольствия - в лице знойной «нефтяной принцессы» и неотразимой ученой. Герою предстоит схватка с безжалостным врагом, который не остановится ни перед чем, претворяя в жизнь свой разрушительный план.",
 "f-wd207921": "Фильм поставлен по реальным событиям и рассказывает о соперничестве двух атлетов-бегунов, представлявших Великобританию на Олимпийских играх 1924 года в Париже: студента Кембриджа, еврея Гарольда Абрахамса и шотландского миссионера Эрика Лиддела. В центре внимания авторов картины — противостояние двух характеров и двух противоположных мировоззрений.",
 "f-wd221594": "Мелвин Адал, психически неуравновешенный эксцентричный писатель, ненавидит буквально всех вокруг. Из-за своего странного поведения он одинок и часто попадает в комичные ситуации. Но неожиданно его уединение нарушается. Мелвину приходится ухаживать за соседской собакой, и незаметно для себя он учится у нее доброте и преданности. За стеной собственного равнодушия ему открывается прекрасный мир человеческих чувств…",
 "f-wd200672": "Жизнь владельца небольшого книжного магазина, расположенного в одном из скромных районов Лондона под названием Ноттинг Хилл, кардинально меняется, когда к нему, чтобы купить путеводитель, заходит известная звезда кино.",
 "f-wd454398": "Спасаясь от злого волшебника Гаргамеля, крошечные смурфики оказываются за пределами родной деревни. Из своего волшебного мира они попадают прямиком в наш мир, а именно в Центральный парк города Нью-Йорк. Теперь маленьким отважным смурфикам предстоит отыскать дорогу домой и не попасть в лапы Гаргамеля.",
 "f-wd108525": "В основе сюжета — борьба полиции с королем преступного мира, знаменитым гангстером Аль Капоне, которого, как известно, удалось засадить за решетку лишь как лицо, уклоняющееся от уплаты налогов. В Чикаго 1931 года криминальная жизнь бьет ключом. Для того, чтобы остановить хладнокровного и неуязвимого Аль Капоне, правительством создана специальная команда «неприкасаемых». Герои Роберта Де Ниро и Шона Коннери вступают в смертельную схватку.",
 "f-wd271281": "1941 год, Вторая Мировая война. Юный англичанин Джим Грэхем живет в богатой семье в Китае. Японцы вторглись в Шанхай, Джим теряется в толпе и остается без родителей в захваченном городе. Во время скитаний находит друга Бэйзи, с которым попадает в лагерь заключенных.",
 "f-wd31271382": "Супершпион Лэнс Стерлинг и молодой учёный Уолтер Беккет — полные противоположности. Жизнерадостный Лэнс с удовольствием каждый день спасает города и страны. Хмурый Уолтер хочет отгородиться от всех в мире собственных изобретений и гаджетов. Но когда события принимают неожиданный оборот, этот маловероятный дуэт вынужден объединиться и проявить все свои способности в совершенно новом ключе. Странной паре потребуются невероятные чудеса маскировки ради спасения всего мира.",
 "f-wd15616479": "4 пингвина - Шкипер, Ковальский, Рико и Прапор, объединяются с командой «Северный ветер», помогающей беззащитным животным. Им предстоит остановить злобного осьминога, доктора Октавиуса Брайна, желающего уничтожить мир.",
 "f-wd222023": "Люси, Сьюзен, Эдмунд и Питер возвращаются в Нарнию. В Англии прошло совсем немного времени, а в Нарнии - века. Страна находится под гнётом зловещего короля Мираза. Но у волшебного королевства есть одна надежда - юный принц Каспиан. Чтобы помочь Каспиану отвоевать трон, четверо героев собирают армию мифических существ во главе с Асланом...",
 "f-wd212123": "Две молодые американки Вики и Кристина проводят свои летние каникулы в Барселоне и совершенно очарованы этим городом, а также одним молодым художником по имени Антонио. Вики — старомодна и настроена на серьезные отношения: ухаживания, свидания и свадебную фату в финале. Кристина — сексуально раскрепощена, раскованна и привлекательна в своей бунтарской сущности. Антонио не может определиться, его привлекают обе девушки. Отношения в любовном треугольнике становятся все более запутанными, а тут еще в игру вступает бывшая жена Антонио, обладающая весьма взрывным темпераментом, и похоже на то, что она не до конца отказалась от своих прав на бывшего мужа.",
 "f-wd255342": "В Лос-Анджелесе злодеи похищают маленькую дочь китайского консула, которую в Гонконге учил кунг-фу инспектор Ли. Консул вызывает Ли в Америку, чтобы тот принял участие в освобождении девочки. Агенты ФБР обратились к полиции с просьбой выделить им самого никчемного сотрудника, чтобы тот взял китайца на себя и не позволял ему вмешиваться в их дела. Им оказывается самый болтливый полицейский Картер. Естественно, после ряда разногласий и недоразумений они объединяют усилия и всерьез берутся за вызволение заложницы.",
 "f-wd213773": "В отличие от всех других людей и животных, девочка Ферн знает, что поросёнок Уилбур — совершенно особенное существо. После переезда на новую ферму Уилбур находит себе ещё одну подругу — паучиху по имени Шарлотта. Их дружба показывает всем животным вокруг, что физические различия не являются преградой для настоящих чувств. Когда приходит известие, что дни Уилбура сочтены, кажется, будто только чудо может его спасти. Но верная Шарлотта ищет способ убедить фермера в том, что Уилбур не заслуживает топора…",
 "f-wd241482": "Генри Рот влюбляется в очаровательную Люси. Несмотря на небольшие помехи, уже к вечеру настойчивому Ромео удается добиться взаимности красавицы. Молодые люди счастливы и уверены, что их любовь продлится вечно. Увы, из-за последствий автомобильной аварии, девушка утром не помнит ничего из того, что произошло накануне. Несмотря на это, Генри не намерен сдаваться и собирается бороться за свою любовь, даже если ради этого ему и придется влюблять в себя Люси каждый день!",
 "f-wd696057": "Обогнуть земной шар всего за 80 дней? Смешно! Даже лучшие паровые корабли Ее Величества Виктории не смогут сделать это. Но точный и пунктуальный Филеас Фогг заявил, что сможет. А когда члены лондонского престижного Реформ-Клуба попросят Фогга подкрепить его похвальбу солидной денежной ставкой, мы отправимся в путешествие Вокруг света в 80 дней!",
 "f-wd3429263": "Получеловек-полувампир Блэйд намерен уничтожить виновника своей судьбы - Дьякона Фроста. Когда-то в кровь Блэйда попало совсем немного вампирского яда, но с течением времени он стал ощущать неизбежность своего превращения. Желая избавить людей от тайной и могущественной армии вампиров, заполонившей общество, он отправляется на решающий бой.",
 "f-wd623336": "Красавица Тина умирает при родах, но перед смертью успевает написать своей новорожденной дочери Анджали восемь писем. В последнем, которое девочка читает, когда ей исполняется восемь лет, мама завещает ей помочь папе воссоединиться с другой Анджали, некогда пожертвовавшей своей любовью ради его счастья с Тиной. Сегодня Анджали как раз выходит замуж, и девочке потребуется преодолеть немало препятствий, чтобы все было хорошо и все запели жизнеутверждающую финальную песню.",
 "f-wd466443": "У богатого бизнесмена и его жены два сына - приемный Рахул и родной Рохан. Рахул дружит с Нэйной, которая влюблена в него, и отец предполагает поженить их. Но Рахул встречает Анджали - симпатичную девушку, живущую в бедном районе, и влюбляется в нее. Несмотря на данное отцу обещание отказаться от девушки, Рахул тайно женится на ней, чем вызывает гнев и проклятия отца. Рахул покидает родной дом и уезжает в Лондон. Проходит 10 лет. Подросший Рохан, чудом превратившийся из неповоротливого толстяка и обжоры в атлета и красавца, узнает о конфликте между отцом и братом и клянется вернуть брата в семью.",
 "f-wd30933418": "Тяжело быть продюсером, когда ты коала и у тебя лапки. Ещё сложнее, когда твоя верная помощница древнее печатной машинки. И совсем весело, когда твоя труппа — это танцующий без остановки пухляш, колючая девочка-панк, застенчивая школьница, верзила-гангстер и многодетная мама, чьи дети — поросята в прямом смысле слова. Рецепт успеха прост — рвануть в мировую столицу развлечений, завербовать легендарного рок-музыканта и взорвать сцену новым шоу.",
 "f-wd662342": "1961 год. Первая советская атомная подводная лодка терпит аварию из-за неполадок в ядерном реакторе. Предотвратить крупную ядерную аварию и потенциальную Третью мировую войну может только экипаж подлодки под командованием капитана Алексея Вострикова.",
 "f-wd385494": "В жизни двух братьев неожиданно возникает отец, знакомый им только по фотографии десятилетней давности. Появление странного, чужого для них человека переворачивает их жизнь, когда отец вырывает ребят из привычного существования в тихом родном городе и привозит на заброшенный остров…",
 "f-wd2990368": "Вторая Мировая война подходит к концу. Тяжёлые затяжные бои изматывают обе стороны. Но чем увереннее наступают советские войска, тем чаще на полях сражений появляется огромным неуязвимый немецкий танк «Белый тигр». Внезапно возникает он в дыму сражений, безжалостно расстреливает своих противников и неожиданно исчезает. Советское командование решает для борьбы с «Белым тигром» создать особый танк — специальную модель Т-34.",
 "f-wd1211800": "«Братья Карамазовы» – это последний роман Ф.М. Достоевского, в котором он затрагивает глубокие вопросы о Боге, морали, свободе. Действие романа происходит в небольшом русском городе Скотопригоньевске, где живёт безответственный и себялюбивый помещик Фёдор Карамазов. Сведя в могилу двух своих жён и воспользовавшись состоянием одной из них, герой прожигает жизнь, пока трое его сыновей – Иван, Дмитрий и Алёша – растут и становятся совершенно разными людьми...",
 "f-wd848825": "У талантливого педагога и переводчика Бузыкина нерешительный характер. Он не может оставить жену и уйти к любимой женщине, не может отказать эксплуатирующей его талант сокурснице, терпит посещения доморощенного философа-алкаша, а когда, наконец, решается на смелый шаг - терпит фиаско, так как по природе мягок и податлив, как воск.",
 "f-wd388266": "Немецкий военнопленный Клеменс Форелль был приговорен к заключению на Колыме. Проработав четыре года на шахтах, он в 1949 году бежал из лагеря.  По пятам преследуемый НКВД, осознавая, что каждый следующий шаг может стать для него последним, он шел через всю Сибирь и Среднюю Азию к иранской границе. 14 тысяч километров и три бесконечных года, проведенных в странствиях, не смогли сломить его стремление к свободе…",
 "f-wd4291959": "Широко развернувшееся в центре Москвы строительство новых зданий приводит к тому, что в одном из тоннелей метро между двумя станциями возникает трещина. Никто себе и представить не мог, что в результате нарушения герметичности перекрытия в тоннель хлынет вода из Москва-реки, и сотни пассажиров поезда окажутся во власти надвигающегося потопа. Бешеный поток воды грозит не только обрушением тоннелей метро, но и разрушением всего города. Среди попавших в беду людей — врач городской больницы Андрей Гарин и его дочь Ксюша. Гарин сражается с катастрофой, пытаясь спасти оставшихся в живых пассажиров, в том числе и... любовника своей жены. Гарину придётся побороть обиду, гнев и страх. Он должен выжить, чтобы вернуть свою любовь, семью... свою прежнюю счастливую жизнь.",
 "f-wd96680099": "Фильм о подвиге подольских курсантов в октябре 1941 года под Москвой. Курсанты подольских артиллерийского и пехотного училищ получают приказ занять оборону на Ильинском рубеже и сдерживать совместно с регулярными частями 43-й армии фашистских захватчиков, пока не подойдет подкрепление. Вчерашние мальчишки, погибая, помогают сдерживать многократно превышающие силы немцев и на двенадцать дней становятся преградой на пути врага к Москве... Картина не только о войне, картина о любви, настоящей дружбе и о том, как мальчики становятся настоящими мужчинами. На последний рубеж перед Москвой были направлены около трех с половиной тысяч курсантов двух подольских училищ и их командиров... Большинство из них остались на рубеже навсегда.",
 "f-wd12507703": "Эпическая сказка, снятая в годы Второй Мировой войны. Русские богатыри Никита Кожемяка и Булат Балагур спасают землю русскую от вражьих полчищ Кащея Бессмертного и освобождают красавицу Марью Мореву.",
 "f-wd2369836": "Артем Колчин был одним из многих, но он хотел славы. И он выбрал свой путь: он стал боксером. Теперь Артем претендент на чемпионский титул, боец, известный по всему миру, Большая Белая Надежда. Но главный бой в его жизни пошел не так, как он ожидал. Теперь ему предстоит решать свои проблемы вне ринга. У него всего три дня, чтобы расквитаться с теми, кто его предал, защитить любимую женщину от наемных убийц и собрать огромную сумму денег. В реальном мире бьют без перчаток и без правил. Вместо ринга — злые улицы большого города. И нет рефери, который может остановить бой. Но боец остается бойцом. Он знает, что такое страх, но способен не бояться. Он продолжает биться, даже когда надежда умерла. Счет идет на часы. И Артем начинает бой. За любовь. За друзей. За собственную жизнь.",
 "f-wd1194343": "Было это давным-предавно. В стороне нашей светлой лесной жил Олень — Золотые рога. Малых, слабых всегда защищал, а вот зла никому не прощал… Но однажды в рассветном часу объявились злодеи в лесу.  Злодейка Баба-Яга утащила и заколдовала двух маленьких девочек. Их мать отправляется на поиски. Сказочный олень Золотые Рога дарит ей волшебный перстень, который поможет в дальнем и опасном пути…",
 "f-wd1195685": "В одном из ковбойских городков Дикого Запада с его традиционной стрельбой, сквернословием и мордобоем появляется тихий миссионер кино мистер Фёст. Неведомое прежде ковбоям «синема» до неузнаваемости меняет уклад их жизни, нравы и привычки. Правда, позднее благородный мистер Фёст будет изгнан недоброжелателями. Но обитатели городка уже никогда не смогут забыть, что на свете есть великое искусство - КИНО...",
 "f-wd7133023": "Немой фильм с подзаголовком «советская бытовая комедия», высмеивающий нэпманский быт и нравы Москвы 1920-х годов. Мелкий чиновник влюблен в очаровательную продавщицу папирос, но она мечтает о красивой и богатой жизни...",
 "f-wd65172370": "Зима 1941 года. Выходя из «Вяземского котла» - немецкого окружения в районе города Вязьма - небольшой отряд советских солдат вынужден остановиться в заброшенной деревне. Передышки не получается. Рядом обнаруживается особое и очень жестокое подразделение карателей Вермахта. Солдаты врага ищут в этих местах таинственного «Красного призрака». Он появляется из ниоткуда и в одиночку убивает захватчиков. Немцы даже не догадываются, что уже находятся под прицелом партизана-супергероя, а советские солдаты собираются вступить в смертельный бой.",
 "f-wd2369847": "Исторический анекдот, удачно и к месту рассказанный, всегда найдет благодарных слушателей, а, тем более, зрителей. История девицы-корнета, желающей наравне с мужчинами защищать отечество, была счастливо вспомнена драматургом А. Гладковым, воплощена им в комедии «Давным-давно» и экранизирована Э. Рязановым в 1962 - к 150-летнему юбилею победы над Наполеоном. Все удачно сложилось в этом киноводевиле: и знакомый сюжет, изобилующий приключениями, переодеваниями, интригами, и замечательная, использующая характерные жанровые модели - романса, баллады, гусарской песни - музыка Т. Хренникова, и звездный актерский ансамбль.",
 "f-wd4366127": "Картина снята по одноименной пьесе Е. Тараховской, в основе сюжета которой четыре русские народные сказки: «По щучьему велению», «Царевна Несмеяна», «Плясовая гармонь», «Емеля-дурачок».",
 "f-wd4366413": "В основе драматической истории - реальные факты биографии летчика-истребителя Алексея Мересьева. Сбитый в бою над оккупированной территорией, он три недели пробирался по заснеженным лесам, пока не попал к партизанам. Потеряв обе ноги, герой впоследствии проявляет удивительную силу характера, вновь садится за штурвал самолета и пополняет счет воздушных побед над врагом.",
 "f-wd4189412": "В основу сюжетной линии положены судьбы декабристов: князя Трубецкого Сергея Петровича, его жены Трубецкой Екатерины Ивановны (урождённой Катрин Лаваль), князя Волконского Сергея Григорьевича и его жены Волконской (Раевской) Марии Николаевны, а также поручика Ивана Анненкова и его жены Прасковьи Анненковой (урождённой Полины Гёбль). После подавления восстания на Сенатской площади события развивались трагически: пятеро декабристов казнены, большинство отправлены в Сибирь. И вслед за ними, сквозь мороз и лишения, поехали их жены…",
 "f-wd4163298": "Молодой русский врач работает в захолустном туркменском городке. Пыльные дороги, непроницаемые лица, дома из глины и фанеры, унылое треньканье азиатской музыки, разноязыкая речь, чуждые обычаи… Доктор лечит детей, пытается что-то писать, но конец света для него уже наступил….",
 "f-wd1983714": "В центре Москвы группа оперативников под руководством майора Смирнова готовит операцию по захвату банды вооруженных преступников во главе с загадочным и неуловимым Германом. В неожиданно вспыхнувшей жестокой перестрелке стражи порядка терпят унизительное поражение, а случайно оказавшаяся на месте событий телевизионная съемочная группа снимает и передает в эфир репортаж о милицейском фиаско. Молодая и амбициозная начальница PR-службы Катя Вербицкая предлагает свой план спасения «чести мундира»: московская милиция сможет восстановить свое доброе имя, превратив поимку особо-опасной банды в мультимедийное реалити-шоу.",
 "f-wd86677634": "Овчарка по кличке Пальма вынужденно расстается с хозяином: тот улетает заграницу, а верную собаку не берут на рейс и оставляют прямо на летном поле. Пальма прячется в аэропорту и каждый день встречает самолеты в надежде, что хозяин вернулся. Но время идет… 9-летний Коля — тоже новенький в аэропорту: он потерял маму и переехал к отцу-пилоту, которого почти не знает. Пальма становится для мальчика родственной душой и лучшим другом. А отцу Коли, летчику Лазареву, предстоит заслужить доверие и любовь сына, сделав нелегкий выбор между карьерой и семьей. И найти способ не разлучить друзей, когда за Пальмой однажды возвращается хозяин.",
 "f-wd833579": "Советский разведчик Алексей Федотов под именем Генриха Эккерта отправляется в оккупированную немцами Винницу. Его цель — добыть секретную переписку генерала Кюна со ставкой Гитлера.  Радист, посланный к Алексею для связи, пойман немцами и расстрелян. Федотов вынужден искать связь через подполье, но случайно он узнает, что один из подпольщиков — провокатор. Блестящий профессионал не только выполняет задание по сбору ценнейшей информации, но и, возвращаясь на Родину, прихватывает с собой самого генерала.",
 "f-wd2496853": "Фильм о героической борьбе матросов Балтийского флота против формирований Юденича. Образы героев фильма навеяны подлинными матросскими и красноармейскими письмами, а также - старыми военными песнями.",
 "f-wd2901494": "Третья часть кинотрилогии и жизни и судьбе М. Горького, поставленная по одноименному автобиографическому роману писателя Алеша Пешков приезжает в Казань учиться. Университет для него оказался несбыточной мечтой, пришлось искать работу, жить без пристанища. Думы молодого Пешкова о жизни не менее тяжелы, чем сама жизнь. В минуту отчаяния он решается на самоубийство",
 "f-wd4129506": "На строительство комбината приезжает бригада монтажников-верхолазов, им предстоит осуществить монтаж домны по новому методу. Кое-кто с перепугу уезжает в командировку, а в целом предложение принято и верхолазы приступают к работе. Фильм о непростых характерах простых советских людей, умеющих трудиться, мечтать, любить — строить большое человеческое счастье.",
 "f-wd15040678": "Джерри — оптимистичный, приятный парень, но он душевно болен и в последнее время не принимал назначенные ему препараты. В своих галлюцинациях он видит, как его кот предлагает ему стать серийным убийцей, в то время как его пес пытается убедить его, что он хороший человек. Начав вновь принимать препараты, он переживает короткие периоды ясности, в которые понимает, что в его жизни гораздо больше насилия, чем он себе представлял.",
 "f-wd224069": "Середина XXI века. Линкольн Шесть-Эхо живет в подземном бункере вместе с другими людьми, выжившими после некой глобальной катастрофы. Как и все остальные, Линкольн лелеет надежду оказаться в числе «избранных», которым предоставляется возможность попасть на «Остров» (такое название дали тому месту на планете, которое не подверглось заражению). Однако вскоре до Линкольна доходит, что те, кто живет в бункере, это клоны, служащие «запчастями» для людей, живущих на «Острове».",
 "f-wd125153299": "Смелый водитель автобуса рискует всем ради спасения самоотверженной учительницы и её учеников от бушующего лесного пожара.",
 "f-wd230482": "Юная Саманта Хьюз, живет со своим дядей Эмметом, ветераном вьетнамской войны, в небольшом городке в штате Кентукки. Девушка одержима мыслями об отце, которого она никогда не знала, и о войне, которая отняла его у нее, войне, которую никто не хочет вспоминать…",
 "f-wd107460063": "Писательница Элли Конвей заканчивает уже пятый роман о приключениях шпиона Обри Аргайла, который борется со зловещей тайной организацией. Когда женщина отправляется на поезде к маме, к ней подсаживается развязный длинноволосый мужчина и сообщает, что он — настоящий шпион, а Элли в своих книгах угадала многое из происходящего в действительности, и им немедленно нужно лететь в Лондон на поиски хакера Бакунина.",
 "f-wd21463782": "Генерал Стэнли Маккристал - одиозная фигура в истории антитеррористических операций США. Стремительный взлёт и досрочная отставка из-за скандальной статьи Rolling Stone в 2010 году стали одним из самых обсуждаемых в политических кулуарах событий, вызвав массу слухов и предположений. Фильм основан на документальной книге репортера Майкла Гастингса и посвящен Афганскому периоду в военной карьере Маккристала.",
 "f-wd315732": "Неудачливый бродвейский театральный продюсер уже довольно долгое время перебивается «с хлеба на квас», старается срубить «копейку» даже в самых невероятных ситуациях… хотя, по большей части, получается так себе. Однажды на его горизонте появляется затюканный и невзрачный бухгалтеришка, который подкидывает сумасшедшую на первый взгляд идею, реализация которой позволит им перестать думать о будущем в мрачных, апокалиптических тонах…",
 "f-wd776302": "Не слишком удачливая певица Долорес — любовница владельца казино Винца — не подозревает, что ее избранник не только бизнесмен, но и гангстер, хорошо известный в криминальных кругах. Она понимает это слишком поздно — когда становится свидетелем его преступления.  Полиция прячет Долорес от преследователей в таком месте, где ее никогда не станут искать… в монастыре, к несчастью для нее, не мужском.  Чтобы скоротать время, новоиспеченная «сестра» решает приобщить монахинь к прекрасному… и церковные песнопения превращаются в дискотеку. Когда душа поет, даже сатана не мешает танцевать!",
 "f-wd275120": "Стив Роджерс добровольно соглашается принять участие в эксперименте, который превратит его в суперсолдата, известного как Капитан Америка. Роджерс вступает в вооружённые силы США вместе с Баки Барнсом и Пегги Картер, чтобы бороться с враждебной организацией ГИДРА, которой управляет безжалостный Красный Череп.",
 "f-wd55081822": "В начале 1960-х Генри Форд II принимает решение улучшить имидж компании и сменить курс на производство более модных автомобилей. После неудавшейся попытки купить практически банкрота Ferrari американцы решают бросить вызов итальянским конкурентам на трассе и выиграть престижную гонку 24 часа Ле-Мана. Чтобы создать подходящую машину, компания нанимает автоконструктора Кэррола Шэлби, а тот отказывается работать без выдающегося, но, как считается, трудного в общении гонщика Кена Майлза. Вместе они принимаются за разработку впоследствии знаменитого спорткара Ford GT40.",
 "f-wd842720": "Отправившись в секс-тур по Европе, два американских студента и их отмороженный исландский попутчик узнают, что самая сладкая клубничка и самый безбашенный экстрим поджидают их в старушке Братиславе, где восточноевропейские красотки готовы чуть ли ни даром исполнить все желания горячих янки! Вскоре перед туристами гостеприимно распахивает двери отель их грез. Но у любых развлечений есть своя цена, и в этом заведении прайс-лист написан кровью! Сюда часто наведываются любители совсем других забав, и когда они достают свои инструменты, самые больные фантазии меркнут перед их хирургическим мастерством…",
 "f-wd17548046": "Когда ОМН распускают, и Итан Хант остается не у дел, его команда неожиданно сталкивается с разветвленной международной сетью высокопрофессиональных спецагентов — Синдикатом. Это «племя изгоев» одержимо идеей установления нового мирового порядка и планирует серию разрушительных терактов. Итан и компания объединяются с дискредитированным британским агентом Илсой Фауст и приступают к своей самой невыполнимой миссии, понимая, что каждый из них может оказаться на стороне Синдиката.",
 "f-wd60737594": "После оккупации Франции нацистами начинающий мим Марсель Марсо, пытаясь добиться расположения красавицы Эммы, вступает в ряды Сопротивления. Там он берется провернуть опасную операцию: спасти группу еврейских сирот из рук нацистов, переправив их через горы и леса Швейцарии.",
 "f-wd116470707": "Окружной прокурор Маргарет оказывается в весьма щекотливой ситуации: она находится в номере элитного отеля, одежда в крови, в спальне труп молодого человека, с которым она познакомилась нынешним вечером. Судорожно перебирая номера в телефонной книжке, Маргарет находит контакт человека, который «решает проблемы». Вскоре появляется профессиональный чистильщик, который сразу же принимается за дело. Однако спустя мгновение в номер входит ещё один решала, которого вызвала владелица отеля. Теперь двум матёрым спецам, которые привыкли работать в одиночку, придётся действовать сообща, преодолевая взаимную неприязнь.",
 "f-wd114859450": "Памфир — в прошлом контрабандист, ныне зарабатывающий строительными работами. Он вернулся с заработков в родное село накануне зимних праздников. У Памфира есть набожная жена и сын-подросток Назар. И из-за неосторожного поступка сына Памфир оказывается перед необходимостью снова нарушить закон, хотя и клялся больше этого не делать.",
 "f-wd107390449": "Сергей Кравинов родился в семье русского аристократа, бежавшего в США в 1917 году. Его мать умерла, когда Сережа был еще маленьким, отец растил сына в строгости, с детства приучая его быть хищником и не показывать слабость перед врагом. Однажды во время охоты на Сергея нападает лев, укусы трансформируют его тело, превращая Кравинова в суперчеловека. Отныне он — Крэйвен-охотник, сверхсильный и выносливый, быстрый и гибкий, подобно зверю. И он докажет миру, что не существует более великого охотника, чем он.",
 "f-wd1546805": "Молодую девушку прямо на улице забирает машина «Скорой помощи» с диагнозом диабет. Находившийся рядом молодой человек хочет поехать вместе с ними, но ему отказывают. Когда он все-таки решает найти понравившуюся ему девушку и приезжает в указанную больницу, ее там не оказывается. Машины «Скорой помощи» с указанными номерами и такого цвета в больнице просто нет…",
 "f-wd124353841": "Компания студентов находит в лесу кулон на цепочке и, забрав его, нечаянно воскрешает неубиваемого маньяка Джонни. Он отправляется на поиски своего сокровища, и всех, кто встретится на его пути, ждёт смерть.",
 "f-wd975358": "До этого дня Том Вицки из Чикаго не верил в гипноз и в теории о скрытых резервах подсознания. Но однажды ему представился шанс испытать все на себе. После того, как Тома загипнотизировали на одной из вечеринок, его жизнь превратилась в клубок странных противоречий и ужасных событий, которые нужно было пережить, чтобы вырваться из когтей окружающего кошмара!",
 "f-wd597046": "История одной мафиозной семьи, жившей в Бронксе в годы Великой Депрессии. Два брата Темпио, Рэй и Чез, хоронят младшего брата Джонни, получившего три пули в грудь. По законам семьи братья обязаны отомстить за его смерть, и Рэй с Чезом пускаются на поиски убийцы. Для начала они должны узнать о жизни Джонни как можно больше, хотя она и так протекала у них на глазах. Однако, на этом пути братьев Темпио поджидает немало неожиданностей. С упорством, свойственным итальянским мафиози, они вершат свой суд. И эта акция имеет трагические последствия для них самих…",
 "f-wd467840": "Группа людей, которые никак друг с другом не связаны, неизвестным образом внезапно оказываются в странной кубической комнате, каждая грань которой снабжена люком, ведущим в другую такую же комнату. Единственная разница между комнатами — это их цвет и наличие разнообразных смертоносных ловушек. Совместными усилиями эти пятеро пытаются найти ключ к выходу из этого гигантского сооружения.",
 "f-wd126511469": "В альтернативной Америке, 100 подростков участвуют в жестоком ежегодном соревновании, известном как Долгая прогулка. Участники должны постоянно идти вперёд с установленной скоростью, не имея права остановиться или сойти с маршрута. За нарушение правил следуют предупреждения, а после 3-ёх предупреждений участника \"исключают\". С каждым часом физическое и психологическое напряжение растёт, а число участников неумолимо сокращается. Для каждого из них прогулка становится испытанием на выносливость, волю и способность оставаться человеком.",
 "f-wd127382372": "Профессор колледжа оказывается на личном и профессиональном распутье, когда выдающаяся ученица выдвигает обвинение против одного из своих коллег, и мрачная тайна из её собственного прошлого грозит выйти наружу.",
 "f-wd160060": "Сюжет ленты расскажет о герцоге, который готовится вступить в должность британского короля Георга VI, отца нынешней королевы Елизаветы II. После того, как его брат отрекается от престола, герой неохотно соглашается на трон. Измученный страшным нервным заиканием и сомнениями в своих способностях руководить страной, Георг обращается за помощью к неортодоксальному логопеду по имени Лайонел Лог. После серии неожиданных техник и в результате дружбы двух непохожих людей, герой наконец обретает свой королевский голос и смело ведет Англию на войну.",
 "f-wd1199513": "«Азиатский ястреб» - так назвали героя Джеки в Европе. Когда он похитил в Африке ритуальный меч, то не предполагал, что это начало опасных приключений. Оказывается, что меч - часть древних доспехов Бога, и если их уничтожить, то в мире будут править силы Ужаса и Зла. Силы Зла, которые укрылись в неприступном монастыре, узнают, что у Джеки есть доступ к остальным доспехам. Они похищают девушку, которую любит Ястреб, и требуют выкупа. Понимая, что одной ловкостью ему не справиться с полчищами бандитов, Джеки добровольно становится человеком - бомбой. Но этот козырь он приберег на самый крайний случай...",
 "f-wd3719894": "Действие фильма развернется в одном из глухих сибирских поселков. Юный главный герой по имени Колыма оказывается впутан в жестокий криминальный мир своего родного городка. Мы увидим становление этого мальчика, которому приходится принять правила их общины и пуститься во все тяжкие. Жить «по понятиям» его научит матерый авторитет — дед Кузя.",
 "f-wd105970894": "Поселившись в Грин Хилз, Соник стремится доказать, что у него есть все задатки настоящего героя. И геройское испытание не заставляет себя долго ждать: злодейский доктор Роботник вновь строит козни. На этот раз с загадочным напарником Наклзом. Вместе они разыскивают бесценный изумруд, в котором заключены силы, способные уничтожать целые цивилизации. Соник объединяется с лисёнком Тейлзом, чтобы отправиться в кругосветное путешествие и найти изумруд до того, как он попадет в плохие руки.",
 "f-wd223596": "Фильм нам расскажет о профессоре Ксавье и Магнито, о процессе основания школы Ксавье для детей-мутантов и, наконец, о том, что же произошло между двумя закадычными друзьями и почему они расстались.",
 "f-wd1358271": "На удаленном острове семь будущих агентов ФБР проходят решающий тест, чтобы попасть в элитный отдел «охотников за разумом» - людей, по мельчайшим уликам и любым сведениям составляющих психологические профили опаснейших преступников. Но испытание становится слишком реальным, когда в их группе оказывается настоящий серийный убийца. Успеют ли оставшиеся в живых выявить маньяка в своих рядах, пока он не расправился с каждым поодиночке?",
 "f-wd1146977": "Банда наемников отправляется на перехват океанского пассажирского лайнера с целью захвата драгоценностей и денег. Вооруженные до зубов, они рассчитывают на успех этой тщательно спланированной операции.Но боевая уверенность захватчиков сменяется ужасом перед небывалыми чудовищами, устроившими пир на корабле! У этих монстров здесь не было противников! И кровь тысяч людей не смогла утолить их жажду!",
 "f-wd1418089": "В недобрый час компания студентов оказалась в заброшенном мотеле под названием «На полпути». Они и не подозревали, что в самом деле застряли «на полпути»: на перепутье между светом и тьмой, ночью и днем, живыми и мертвыми.  Отрезанные от всего мира, они попали в ловушку к кошмарному, издающему невыносимый тошнотворный запах монстру, открывшему на них охоту. Чтобы дожить до утра, им нужно не только узнать, что же такое РИКЕР, но и понять одну вещь: если хочешь жить, не надо бояться смерти…",
 "f-wd19264018": "Гигантские черви-людоеды, известные как Грабоиды, терроризируют жителей Южной Африки. И самое страшное — это то, что Грабоиды со временем превратились в еще более опасных тварей…",
 "f-wd15894174": "Несколько не очень хороших полицейских пытаются избавиться от тела человека, которого один из них случайно застрелил.",
 "f-wd73093591": "1940 год. Герман Манкевич, нью-йоркский острослов, когда-то приехавший покорять Голливуд и в целом преуспевший, с переломами после автоаварии уединяется в домике посреди пустыни Мохаве. Он помещён в заточение продюсером Джоном Хаусменом и молодым режиссёром Орсоном Уэллсом: Манк — так называют его друзья — должен всего за три месяца написать для Уэллса сценарий. А лучше бы за два.",
 "f-wd23755544": "Команда афро-американок проводит для НАСА ряд математических вычислений, необходимых для запуска первой космической миссии.",
 "f-wd798797": "Учительница средних классов живет гламурной жизнью светской львицы, ходит на работу как на вечеринку и мечтает об увеличении объема собственного бюста. Однако после внезапного разрыва с богатым бойфрендом ее образ жизни резко меняется, хотя сама она это осознает не сразу. Но когда в их школу приходит новый преподаватель, она совершенно теряет голову и начинает охоту за... деньгами.",
 "f-wd65032692": "В поисках пропавшей матери отважная девушка Энола Холмс использует свои детективные навыки, чтобы перехитрить старшего брата Шерлока и помочь беглому лорду.",
 "f-wd4407383": "Фильм основан на реальных событиях - величайшей охоте на сокровища в истории. Во время Второй мировой войны команда из искусствоведов и хранителей музеев объединяется, чтобы спасти известные произведения искусства, похищенные нацистами, прежде чем те успеют их уничтожить.",
 "f-wd107808351": "Недавний выпускник колледжа Джейми Рейес возвращается домой, полный надежд на свое будущее, только для того, чтобы обнаружить, что дом не совсем такой, каким он его оставил. Пока он пытается найти свое предназначение в этом мире, вмешивается судьба, когда Джейми неожиданно оказывается обладателем древней реликвии инопланетной биотехнологии: скарабея.",
 "f-wd429934": "В недалёком будущем космический корабль терпит бедствие, в результате чего совершает вынужденную посадку на отдалённой планете. Но в результате такой посадки погибает командир корабля, часть команды и большинство пассажиров. Оставшиеся в живых оказываются одни на жуткой и безжизненной планете. Первое, что бросается в глаза — это то, что планета имеет три солнца, из-за чего всё живое погибает в этой пустыне. Но как только планета погружается в темноту, появляются какие-то странные существа…",
 "f-wd24905490": "Фильм расскажет о последних днях Сталина и о хаосе, охватившем страну, после его смерти.",
 "f-wd55657425": "Вся семья главной героини погибает во время массового расстрела. Сама она чудом остается в живых — мать закрыла ее своим телом. Больше двух лет девочка живет, прячась в нерабочем камине в комендатуре, пока деревню не освобождают от нацистов. Невероятно, но Анне удается не только выжить, но и сохранить в себе человека. Ей помогают в этом её собственные воспоминания о родителях, доме, а также друг, который спасает её от полного одиночества.",
 "f-wd1969046": "Они виделись всего раз. На пьяной свадьбе. Их взгляды встретились. Это оно. То, чего они никогда не знали, то, что они не могут понять, осознать, произошло. Теперь им невозможно жить, дышать друг без друга. Словно мощным речным потоком, сильным космическим магнитом с непреодолимой силой манит, влечет, притягивает их друг к другу. Они уже не принадлежат себе, своим родным и друзьям.",
 "f-wd4365896": "Школьник-отличник Руслан Чутко, одержимый стремлением очистить город от преступников, вступает в оперативный отряд. Но постепенно он сам становится разрушающей силой, не приносящей людям ничего, кроме зла - потому что живет по принципу «цель оправдывает средства». Но однажды во время облавы на браконьеров среди нарушителей оказывается его отец...",
 "f-wd106261959": "Сергей и Кира считались самой красивой парой богемного Петербурга начала девяностых. Это были интеллектуалы, влюбленные в кинематограф. Но счастливая романтическая история обернулась жесткой драмой. Она сбежала в другой город, в другую жизнь, в другую любовь. А он остался в Петербурге и умер вскоре после развода. И только спустя семнадцать лет красивая и успешная Кира осознает, что нет у нее больше шансов на счастье, так как ее сердце навеки отдано Сергею.",
 "f-wd174371": "Неудержимый скалолаз и любитель спрятанных в каньонах пещер в очередной раз в одиночестве едет в горы и оказывается в смертельной ловушке. 127 часов без еды, без питья и практически без надежды выжить. Тут-то и проявляется сила характера...",
 "f-wd21640541": "Игорь - старший менеджер в мебельном салоне, мечтающий о повышении. На следующий день после корпоративной вечеринки он обнаруживает, что салон полностью разгромлен. Сотрудники утверждают, что когда они уходили, всё было в порядке. Игоря это не устраивает, ведь теперь на кону его карьера. Пытаясь выяснить, что же произошло, Игорь узнаёт шокирующие подробности о ночных приключениях своих коллег...",
 "f-wd3939300": "В результате опустошительной межпланетной войны практически разрушена Земля и соседние планеты. Могущественные победители, воины — Терадаксы правят на Земле. Только Гибсон — величайший воин-робот способен противостоять инструменту смерти роботов, внушающему ужас Голиафу.",
 "f-wd113641997": "Вуди, Джесси и Базз Лайтер сталкиваются с новой угрозой — планшетом «ЛилиПад», который стал любимой игрушкой 8-летней Бонни и занимает всё больше её времени.",
 "f-wd785157": "Неожиданный оборот принимает генетический эксперимент, во время которого новорождённых близнецов, которые, кстати, совершенно непохожи друг на друга, разлучают на долгие годы. Но несчастные братья наконец встречаются... Джулиус, образованный, но совершенно не знающий жизни гигант с добрым сердцем и Винсент, коротышка с неистребимой жаждой денег и женщин. В компании подружек и преследующего их наёмного убийцы братья отправляются в путешествие по стране на поиски своей матери — но в конце концов находят гораздо большее. Только мать может сказать им правду.",
 "f-wd10743149": "Ретро-драма по одноимённой пьесе Леонида Зорина 1960-х годов о людях одного поколения, на судьбах которых по-разному отразились наиболее важные этапы жизни Страны Советов 30–60-х. Песню «Это было недавно» исполняет Олег Анофриев.",
 "f-wd116536092": "Партибан живёт в небольшом городке вместе с женой и двумя детьми. Он управляет кафе и периодически занимается спасением диких животных. Однажды вечером в его заведение заходят опасные бандиты, которые после заказного убийства пытаются добыть денег и скрыться. Понимая, что его вместе с маленькой дочкой как свидетелей в живых не оставят, Партибан вступает в бой с преступниками, и, завладев оружием, убивает их всех. Ситуация получает широкую огласку в прессе, а лицо героя появляется на первых страницах газет. Вскоре данная информация доходит до главаря криминальной группировки, который узнаёт в Партибане своего погибшего сына, которого звали Лео Дас.",
 "f-wd115947372": "Молодой человек не может наладить отношения с отцом и постепенно теряет и свое окружение. В результате он остается один на один с миром, полным нечеловеческого отношения к нему, что делает его настоящим зверем.",
 "f-wd86751411": "Пушпа - грузчик, который пробивает себе путь в мире контрабанды красного сандалового дерева. По пути он не стесняется нажить себе одного-двух врагов...",
 "f-wd105952623": "Парень из трущоб перебивается участием в подпольных боях без правил. В детстве он стал свидетелем убийства матери коррумпированным полицейским, и с тех пор им движет только жажда мести. Получив работу на кухне элитного борделя, который посещает убийца, молодой мститель начинает действовать.",
 "f-wd132794955": "Юному герою поручено защищать девять священных свитков, которые способны превратить смертного в божество. Эти артефакты становятся объектом охоты зловещей группировки «Чёрный Меч». Чтобы спасти мир, герою предстоит пройти путь от обычного человека до избранного воина.",
 "f-wd115945804": "Индия, 1975 год. Индира Ганди в ответ на массовые выступления против своего правления объявляет в стране чрезвычайное положение.",
 "f-wd136222258": "Раненая женщина с младенцем на руках убегает от вооружённых солдат. Понимая, что долго не протянет, она возносит последнюю молитву богам и просит спасти жизнь ребёнка, а сама погружается на дно реки, держа младенца в вытянутой руке над водой. На следующий день его находят местные жители и решают усыновить. Спустя годы мальчик превращается в крепкого и рослого парня Шивуду, наделённого невероятной силой. Однажды он находит маску и решает во что бы то ни стало разыскать её владельца, не подозревая, что она принадлежит прекрасной воительнице Авантике, которая всем своим кланом пытается вызволить королеву Девасену из плена тирана Бхаллаладевы.",
 "f-wd110263831": "Несчастный мужчина по имени Канти просит суд включить уроки полового воспитания в школьную программу.",
 "f-wd640276": "Действие фильма происходит в 1860 году в бенгальской деревне Чандипур. Дойамойи и её муж Умапрасад живут с его старшим братом, его женой и богатым отцом Каликинкаром Роем. Каликинкар Рой, стареющий вдовец, поклоняется индуистской богине Кали. Умапрасад, муж Дойамойи, уезжает на учёбу в Калькутту, а она остаётся ухаживать за старым тестем. Каликинкару Рою во сне приходит откровение, что его невестка является воплощением богини Кали, и он настаивает, чтобы ей поклонялись. Однажды он помещает у её ног умирающего ребенка и тот чудесным образом выздоравливает. Эта новость быстро распространяется и сотни престарелых, больных и бедных устремляются к Дойамойи за помощью. Умапрасад узнаёт об этих событиях и возвращается домой, чтобы образумить своего отца. Однако отец не слушает его.",
 "f-wd874521": "Сын промышленного магната Радж встречает Прийю на свадьбе своего друга и уже не может представить своей жизни без неё. Вскоре молодые люди женятся и на радость всем ожидают пополнения в семействе. Но происходит непоправимое, из-за неудачного падения у Прийи происходит выкидыш и, как последствие, поставлен диагноз - бесплодие. Не желая расстраивать родных, Радж и Прийя скрывают от них это и...",
 "f-wd624722": "Фильм о безграничной любви и преданности матери к своему ребенку, о жизни женщины, принесенной в жертву ради сына. Молодой летчик влюбляется в очаровательную девушку. Но он погибает, а девушка рожает незаконного ребенка. Она отдает его в семью, а сама устраивается туда няней. Родственник хозяев пристает к женщине и маленький мальчик (ее сын!) убивает его. Мать идет в тюрьму вместо сына…",
 "f-wd585892": "Ауро — 13 летний мальчик, страдающий от неизлечимой болезни прогерии. Хотя и выглядит он 80-летним стариком, по собственному физическому развитию он не отстает от собственных ровесников. Мальчик увлекается игрой в крикет и грезит отыскать отца. Однажды в школу приезжает депутат парламента Амол Арте, чтобы вручить Ауро кубок за победу на конкурсе.",
 "f-wd151529": "Фильм повествует о молодом мечтателе и начинающем актёре из Индии, пытающемся покорить Голливуд. Для этого он переезжает в Лос-Анджелес, и сперва играет незаметные роли в местных театрах.Но настоящая слава приходит к нему после того, как он попадает в курьёзную ситуацию, и встречается с двумя звёздами Голливуда — Сильвестром Сталлоне и политиком Арнольдом Шварценеггером…",
 "f-wd1255514": "За борьбой двух телеканалов на экранах своих телевизоров наблюдала вся Индия. Ведущие телевизионных программ K-TV Аджай Бакши и «Гэлакси» Риа Банерджи поначалу ввязались в острую конкурентную борьбу, стараясь раньше других сообщить зрителям самые свежие новости. И делали они это блестяще. Однако погоня за сенсацией не мешает молодым людям трезво смотреть на жизнь. Особенно это проявилось во время подготовки к новым парламентским выборам, когда их хозяева (соответственно Кака Чаудхари и мистер Ниной) стали с пеной у рта защищать позиции Премьер-министра Мушрана и главы оппозиции Рамаканта Дуа. В этой резко обострившейся политической ситуации Аджай и Риа вдруг почувствовали, что их трепетные сердца бьются в ритме любви...",
 "f-wd737318": "Они уехали в далекий Мельбурн искать свое счастье. Он и она уже многого добились в жизни. Никхил стал высококлассным поваром, а Амбар - популярной ведущей радиостанции. Но однажды они встречаются, становятся друзьями и начинают жить в одном доме, правда, в разных комнатах..",
 "f-wd3420017": "Перед дочерью политика Арти была открыта дорога на политический Олимп, но она вышла замуж за Джей Кея и карьера отошла на второй план, но только на несколько дней. Исполненная амбиций, она оставляет мужа и дом и становится виртуозным политиком.  Год спустя, во время очередной компании, она снимает номер в отеле только чтобы встретиться с мужем, к которому снова испытала чувства. Ее политические оппоненты используют эту возможность и раздувают скандал. Полная смущения она признается, что это ее муж. Она уже готова отступить, но будет ли этого достаточно?…",
 "f-wd1433549": "Деревенская девушка Мускан и городской парень Сурадж, познакомившись в колледже, влюбляются друг в друга. Но у Мускан есть чрезмерно опекающий ее брат, который регулярно навещает девушку. Во время одного из таких визитов Сурадж, приняв его за поклонника Мускан, затевает с ним драку. Рассерженный брат принимает решение забрать девушку обратно в деревню. В надежде исправить ошибку и вернуть возлюбленную за ними следует Сурадж.",
 "f-wd16250359": "Мили Чакраворти талантливый физиотерапевт, посещает королевскую семью, чтобы лечить больного короля, Шекхара Раторе. Родом из семьи среднего класса, спонтанная девушка, она не собирается следовать строгим правилам, установленным властной хозяйкой дома Раторе, Нирмалой Деви. По закону притяжения противоположностей, Мили встречает благородного и учтивого принца Викрама, и в её сердце расцветает любовь. Сможет ли Мили с её неуклюжим характером завоевать расположение этой семьи или она останется неподходящей партией для принца?",
 "f-wd1493345": "ействие фильма происходит в маленьком городке в Бенгалии. Доктор Ашок Гупта руководит местной больницей. Младший брат доктора, Нишрит, возглавляет комитет, занимающийся вопросами больницы и храма, которые были построены местным промышленником. Храм также является крупной туристической достопримечательностью. Доктор Гупта уверен, что святая вода в храме загрязнена из-за повреждения труб и это является причиной эпидемии в городе. Он предупреждает об этом своего брата Нишрита. Нишрит, промышленник и другие официальные лица города отвергают мысль о том, что святая вода может быть причиной эпидемии, и отказываются закрыть храм для проведения ремонта. Доктор Гупта хочет написать статью в газете, чтобы предупредить людей, но редактор под давлением влиятельных лиц отказывается публиковать её. Тогда доктор Гупта пытается организовать общественное собрание, которое также саботировали, а доктора провозгласили врагом народа.",
 "f-wd797444": "Балрай Капур - богатый бизнесмен с прогрессивными взглядами на жизнь. Для него семейное благополучие - главная ценность. Шобхна - намного больше, чем просто лучшая половина Бапрая. Вместе они всеми силами опекают и лелеют своего единственного ребенка, Авинаша, который Балраю скорее друг, чем просто сын. Авинаш много лет провел за рубежом, получая образование. И вот, долгожданный сын возвращается домой на радость родителям. Вскоре он влюбляется в прелестную художницу Милли, их счастливый брак вознаграждается милым ребенком.",
 "f-wd2041431": "В конце худшего дня своей жизни Арун Праджапати гневно бунтует против Бога за то, что тот делает его жизнь несчастной. К его удивлению, Господь является ему в человеческом облике и обеспечивает Аруна своими божественными полномочиями. Он бросает Аруну вызов: сможет ли тот взяться за большую работу и выполнить ее лучше всех? Арун берется за свою миссию с искренним рвением, но попадает в одну беду за другой. Любовь его жизни Алия с изумлением смотрит на «нового» Аруна, активного и уверенного в себе. Арун думает, что он сможет сделать мир счастливым местом, где исполняются желания каждого человека. Но Арун осознает, что быть Богом намного труднее, чем он думал.",
 "f-wd123901928": "Жизнь двух братьев из скромной деревни разрушается людьми из богатой семьи. Сможет ли главный герой преодолеть сложные ситуации и прожить счастливую жизнь со своими близкими?",
 "f-wd3127192": "Группа неуклюжих танцоров принимает участие в международном конкурсе танца. Не то, чтобы они мечтали о победе, главная их цель — ограбить банк в Дубае…",
 "f-wd123862092": "Дде две семьи везут Мину на ритуал к шаману из-за того, что она влюбилась в неподходящего парня.",
 "f-wd169564": "История двух родительских пар, которые знакомятся после того, как их сыновья сходятся в школьной драке. При этом каждая пара оспаривает родительские навыки другой, вместо того, чтобы разглядеть собственные проблемы.",
 "f-wd32303": "После развода учитель живет одинокой жизнью, пытаясь восстановить отношения со своим сыном-подростком. Постепенно он находит любовь и получает хорошие новости от сына, но эта удача вот-вот будет жестоко разрушена невинной ложью.",
 "f-wd507490": "Действие фильма происходит в Нью-Йорке весной 2003 года. Для Нэйны Кэтрин Капур зима продолжается. Зима в сердце, потому что со дня смерти отца вся жизнь ее подчинена бесконечным выяснением отношений в семье. Забота о маленькой сестре и брате, помощь матери Дженнифер, несносный характер бабушки - вот ее жизнь. Вечеринки, забавы и шутки обходят ее стороной. Ей 23 года, но в душе она уже бабушка - серьезная и скучная. Аман Матхур- свежее дуновение в ее жизни. Он знает, как разрешить любую проблему. Но Нэйне не нравится оптимизм и напористость Амана. Ее улыбка - отныне цель жизни Амана и ради этого он зовет на помощь манхеттенского бакалавра медицины Рохита, чтобы он помог растормошить девушку. Когда кажется, что жизнь заиграла новыми красками, понимаешь, что для некоторых эти мгновения являются последними. Наступит завтра или нет?..",
 "f-wd1341875": "В нищем и грязном районе, в унылом бараке, превращенном в больничку, ведет прием пациентов врач. Однажды к нему обращается за помощью молодой хулиган, раненный в драке с местными гангстерами.\r Врач обнаруживает у своего непокорного пациента туберкулез. И постепенно, стараясь завоевать доверие, задобрить злобного парня, привязывается к нему, старается не только вылечить, но и спасти его от одиночества, отчаяния, пьянства.\r Снисходительность, доброта и терпение врача пробуждают в угловатом хулигане отзывчивость, благодарность, человечность, солидарность.\r Когда вновь появляются гангстеры, «Пьяный ангел», не желая подчиниться законам преступного мира, законам злобы, бросается на защиту наивной и доверчивой медсестры.",
 "f-wd923911": "Самые счастливые годы Лаура провела в сиротском приюте на побережье. Любимые воспитатели заменили ей родителей, а друзья — братьев и сестер. Через тридцать лет Лаура возвращается в дом своего детства с мужем и семилетним сыном. Она мечтает восстановить его и открыть для новых маленьких посетителей. Однако героиню поразили перемены, произошедшие с ее собственным сыном.Из милого мальчика он превратился в маленького монстра с жестокими фантазиями и опасными играми. Она уверена, что во всем виноват старый дом, таящий скрытую угрозу. Постепенно картины прошлого всплывают в памяти Лауры и открывают ей страшную истину…",
 "f-wd610158": "Япония. 1185 год. Надменные Хэки разбиты на море. Их победитель Миномото Есицунэ должен возвратиться в столицу после своих доблестных подвигов. Но Миномото Еримото, известный своей подозрительностью, поверил злословью вассала Киновара и решил убить Есицунэ — своего младшего брата.  Объявленный вне закона по всей Японии Есицунэ и шесть его верных вассалов, переодевшись в монахов, пробираются на север по провинции Фудживара Кидихиро. Приблизившись к враждебной заставе Атака, они решают пересечь перевал…",
 "f-wd1350521": "Пугающий рассказ о 12-летнем Карлосе, который после смерти отца попадает в школу Санта-Лусии на попечение директрисы Кармен и профессора Касареса. Отец мальчика был мятежником, убитым в сражении против режима Франко. И хотя приют перегружен большим количеством детей, директор школы сочувствующе принимает молодого Карлоса.",
 "f-wd743203": "Фильм рассказывает историю пожилого человека, который в одиночку воспитал дочь и теперь хотел бы выдать её замуж, как ни мучительно и горько им расставаться друг с другом.",
 "f-wd498277": "Фильм об авантюристе, который выдал себя за знаменитого режиссера Мохсена Махмальбафа, проник в зажиточный дом (якобы для съемок) и был арестован по подозрению в мошенничестве и грабеже. Судебный процесс составляет сюжетную канву фильма, но истинный его предмет — это особый статус кино в Иране. Кинематограф здесь стал не только частью духовной жизни элиты, но и элементом личного и национального престижа, достоянием широких масс.",
 "f-wd1091097": "Герой этого фильма по имени Кикуджиро не может похвастаться умом и хорошим вкусом. Он не любит работать и не умеет плавать, но зато может сквернословить и жульничать. Кикуджиро обожает азартные игры, и частенько разрешает жизненные проблемы при помощи кулака. Но случилось так, что именно этого наглого и безответственного субъекта судьба выбрала на роль компаньона и защитника для крошечного, ангелоподобного и очень одинокого мальчугана по имени Масао.  Тихий и молчаливый малыш Масао мечтает увидеть свою маму, которая давно переехала на побережье, оставив ребёнка на попечение бабушки. Вместе с великовозрастным хулиганом Кикуджиро мальчик отправляется к морю на поиски мамы. Эту невероятно странную парочку ждёт захватывающее и полное приключений путешествие.",
 "f-wd1382421": "Стокгольм, 50-е годы прошлого века. Отчим 16-летнего Эрика «в воспитательных целях» регулярно избивает своего отпрыска, который в любой конфликтной ситуации тоже всегда готов пустить в ход кулаки. После очередной драки в школе Эрика отправляют в частную школу-интернат, где учащиеся старших классов занимаются воспитанием младшего поколения.  Эрик противостоит всему миру, который, кажется, всеми силами пытается не дать ему добиться своей цели — ученой степени. Он не слушает ничьих советов, и окружающим это не нравится.",
 "f-wd27964540": "Самый смертоносный спецназовец Китая поселился в спокойной жизни на море. Когда садистские наемники начинают атаковать близлежащих гражданских лиц, он должен оставить свой новообретённый мир позади и вернуться к своим обязанностям солдата и защитника.",
 "f-wd169322": "В послевоенный период эксперты по дому и домашнему хозяйству обнаружили, что одна лишь правильная организация рабочего места на кухне с использованием принципов заводского конвейера может принести огромные финансовые выгоды домашнему хозяйству. Или, как было сформулировано в шведской рекламе новой идеальной кухни: вместо того, чтобы пройти расстояние от Швеции до Конго за год приготовления пищи, домохозяйке теперь потребуется дойти только до Северной Италии, чтобы поставить обед на стол.\r После того, как шведские ученые из Института исследования дома составили подробную карту перемещений шведской домохозяйки по кухне и досконально изучили ее поведение, они почувствовали, что готовы преодолеть поставленные перед собой географические и основанные на половом признаке ограничения. В начале 1950-х они отправили 18 наблюдателей в сельский регион Норвегии Ландстад, где был избыток холостяков, чтобы исследовать, как ведут себя на кухне неженатые мужчины.",
 "f-wd1472478": "Вокруг нее всегда крутятся странные мужчины. Ее возлюбленный — вуайерист. Ее свекор — маньяк. Брат ее служанки — сбежавший из психушки насильник. А сама она — маникюрша Кика — обладает поразительной способностью притягивать к себе всевозможные неприятности и недоразумения…",
 "f-wd1990204": "Фильм рассказывает о нелёгком труде женщин на военном заводе. Героини выведены не патриотично-иступлёнными автоматами, а живыми людьми, тонко чувствующими и способными на глубокие переживания.",
 "f-wd65267432": "2092 год. Из-за глобального загрязнения Земля становится непригодной для жизни, поэтому компания UTS с помощью нанотехнологий планирует терраформировать Марс. Но в светлое будущее возьмут далеко не всё население, и команда космического корабля «Победа» в число этих счастливчиков не входит. Нищеброд Тхэ-хо, красавица-капитан Чан, матёрый механик Тайгер Пак и робот, как и многие другие, пытаются заработать сбором космического мусора, но всё больше залезают в долги. Однажды они находят с виду безобидную девочку-андроида, которая, как выясняется, является оружием массового поражения. Наши герои решают наладить свою унылую жизнь и выгодно продать находку.",
 "f-wd643268": "Жителям тихого датского городка вдруг приспичило выучить итальянский язык. С каждым днем число фанатиков растет, хотя в группе даже учителя нет — но всем по барабану: одинокие люди, испытывавшие поначалу чувство отчуждения, постепенно приходят к выводу, что счастье искать никогда не поздно. Занятия обретают неслыханную популярность. В группу для новичков зачастила даже коренная итальянка.",
 "f-wd1675604": "Стиг, 15-летний старшеклассник, влюбляется в свою школьную учительницу Виолу. Ей 37 лет, но разница в возрасте и тот факт, что она замужем, не могут остановить стремительно возникшее взаимное чувство.",
 "f-wd2719268": "Паулино и Кармела — супружеская пара бродячих артистов, отправившихся в путешествие по Испании в период гражданской войны 30-х годов. Они, республиканцы, вместе со своим переводчиком Густавете попадают на территорию франкистов. Местный командир делает им предложение поставить спектакль, высмеивающий Республику, в обмен на их свободу и жизнь…",
 "f-wd1464998": "В Японию 90-х годов 20 века прибывают люди из далёкого будущего и заявляют, что если Годзилла не будет уничтожен, то вскоре он станет причиной глобальной ядерной катастрофы. Для устранения такой угрозы они предлагают вернуться в прошлое и ликвидировать Годзиллу до его мутации в непобедимого динозавра. Однако вскоре появляется новая проблема — в лице трёхголового дракона Кинга Гидоры.",
 "f-wd1364843": "После трагической гибели дочери учительница Юко Моригути пришла в класс, чтобы провести свой последний, самый важный урок. После него её работа в этой школе была закончена. Но это было лишь начало запущенного ею изощренного плана мести. Ведь её класс — это далеко не кучка тринадцатилетних ангелков с типичными для пубертата проблемами, а сборище жестоких и хладнокровных подростков, чьи злодеяния в силу малолетства зачастую остаются безнаказанными.",
 "f-wd485709": "Чха Тхэ-щик — скромный с виду владелец ломбарда. Девочка Со-ми — его соседка и дочь матери-одиночки, которая работает в баре, не особо заботится о ребёнке и однажды вместе со своим парнем решает обокрасть наркокурьера. В результате Со-ми похищают, а Тхэ-щик оказывается не таким уж и скромным — он решает любыми средствами спасти девочку.",
 "f-wd24515": "Вражда между китайскими военачальниками достигла своего предела. В безудержном стремлении завоевать соседние территории они погружают страну в пучину раздора. Молодой воин Сяо Че, одержав победу в поединке над одним из шаолиньских мастеров, начинает этим хвалиться. Но самонадеянность к добру не ведёт. В междоусобных распрях гибнет семья Сяо, а ему самому чудом удаётся спастись. Сяо укрывают шаолиньские монахи. Известия о бесчинствах местного «царька» достигают стен монастыря. Сяо Че и его новые друзья решают вмешаться и защитить простых людей от произвола жестокого завоевателя.",
 "f-wd1754392": "Наркомафия убивает мастера боевых искусств, и его младший брат начинает мстить преступникам…",
 "f-wd485462": "Молодой многообещающий гангстер Ким управляет отелем, который принадлежит местному мафиози. Босс поручает Киму задание — проследить за своей молодой подружкой и зафиксировать факт возможной измены. Поручение становится событием, навсегда изменившим его жизнь.",
 "f-wd463907": "Фильм повествует о молодой паре молодоженов, которые вместе играют в шведском оркестре и пробуют найти общий язык, несмотря на две противоположности, которые они представляют.",
 "f-wd1514075": "Расщепление урана в земных недрах вызвало неуправляемую цепную реакцию в теле Годзиллы, превращая его в ядерную бомбу замедленного действия, готовую взорваться в любую минуту.  В это время в одной из лабораторий Токио ученые создают препарат, неверное применение которого приводит к созданию супермонстра «РАЗРУШИТЕЛЯ», уничтожающего все на своём пути. Единственный шанс человечества на выживание — что в чудовищной схватке титанов не будет победителя.",
 "f-wd1931816": "о роману Нагиба Махфуза \"Тупик Милагро\". Действие происходит в бедном районе Мехико и ограничено небольшим двориком, главной достопримечательностью которого является бар дона Рутильо. С его посетителями и знакомит фильм. Зритель постепенно знакомится с многочисленными персонажами, выписанными с теплом и любовью, узнает об их взаимоотношениях, жизни, радостях и проблемах. Чава, сын дона Рутильо, очень хочет вырваться из бедной, однообразной рутины и уехать в Штаты, для чего изучает английский язык. Авель любит местную красавицу Альму (Хэйек), дочь донны Каты. Уже немолодая и щербатая Сусанита, владелица дома, мечтает найти мужчину для своего доброго сердца. Дон Рутильо влюблен в... продавца из магазина одежды, что очень не нравится его пышной супруге и сыну. У Альмы появляется шанс выйти замуж за старого и обеспеченного дона Фиделя, но тот умирает от сердечного приступа за партией в домино.",
 "f-wd770670": "Нынешняя наука повсеместно отказывается от термина «гермафродит», считая его путаным и содержащим осуждение и отдавая предпочтение политкорректному слову «интерсекс». Именно в таком мутном состоянии находится героиня фильма (в равной степени герой) 15-летняя Алекс, которая страдает гермафродитизмом с рождения. Её родители приглашают в их дачный домик на уругвайском побережье супружескую пару из Буэнос-Айреса. А те привозят с собой 16-летнего сына Альваро.  Алекс притягивает этот угловатый закомплексованный юноша. Она хочет проверить свою сексуальность в деле и понять, к какому берегу её влечет. Их интимный контакт окажется неожиданным для обеих сторон. Алекс в шоке от своего пробудившегося не женственного, а совсем даже мужского, а, может, мужеложского инстинкта. Девственник Альваро в шоке от того, что акт содомии, в котором он оказался пассивным реципиентом, ему вдруг понравился…",
 "f-wd1747275": "Хосе-Луис, работающий могильщиком, случайно знакомится с миловидной Кармен, дочерью добродушного старичка Амедео, который, однако, уже 40 лет служит тюремным палачом. Из-за профессии отца Кармен не хватает мужского внимания, а у Хосе-Луиса те же проблемы с девушками - никто не хочет встречаться с могильщиком. Им вместе хорошо, у них рождается ребенок, но когда Амедео уходит на пенсию, начинаются проблемы...",
 "f-wd2983218": "Проведя два года в Лондоне, Аче возвращается домой, чтобы начать новую жизнь: устроиться на работу, завести новых друзей. Однако многое изменилось и встреча с Джин заставляет Аче почувствовать то, что он чувствовал только к Баби — своей первой большой и настоящей любви…",
 "f-wd13218237": "Шахтер Дахай возмущен царящей среди руководителей его деревни коррупцией и решает перейти к действиям. Рабочий-мигрант Сан’ер открывает для себя бесчисленные возможности, заложенные в огнестрельном оружии. Домогательства богатого клиента доводят работницу сауны Сяо-ю до полного отчаяния. Сяо-гуй вынужден менять работу, каждый раз соглашаясь на худшие условия. Четыре персонажа, четыре провинции, отражающие облик современного Китая. Портрет общества, которое переживает бурное экономическое развитие и постепенно заражается бациллой насилия.",
 "f-wd1444725": "В конце Второй мировой войны немцы перевозят бессмертное сердце монстра Франкенштейна в Японию, чтобы не допустить его захвата союзниками. После ядерной атаки США на Хиросиму оно оказывается потерянным. Спустя годы на улицах города появляется дикий мальчик, порожденный бессмертным сердцем монстра.",
 "f-wd1211778": "Пришельцы из умирающей галактики решают переселиться на Землю, уничтожив перед этим её население. Основное оружие агрессоров — огромная Мехагодзилла, вооружённая лазером и ракетами. К тому же на сторону пришельцев переметнулся профессор Мафуни, контролирующий Титанозавра — здоровенного монстра-амфибию. Для Годзиллы этот бой обещает быть сложным…",
 "f-wd1742061": "Подводная цивилизация, недовольная проведением ядерных испытаний вблизи своей территории, отправляет наверх гигантского жука Мегалона, чтобы разрушить Токио. Спасти город может только Годзилла, за которым японцы посылают специально созданного робота.",
 "f-wd2635074": "У сестер Линн и Сью очень необычный и крайне опасный бизнес. Линн — безжалостный киллер-профи, а Сью оказывает ей полную техническую поддержку в выполнении заданий. Смертоносная пара называет себя «Боевые Ангелы» и имеет грозную славу лучших из лучших в криминальном мире.  Но после одного особенно громкого убийства на след сестер нападает дама-полицейский Ят Хонг, не уступающая «ангелицам» ни в хитрости, ни в боевых искусствах. Умная и упорная, она медленно, но верно подбирается к Линн и Сью, еще не ведая, что вскоре сама судьба заставит ее объединить силы со своими противницами и вместе сразиться с новым, могучим и страшным врагом!",
 "f-wd544642": "Детектив-сержант ОБОП Джан Ма, при очередных внутренних проверках, получает нагоняи за частое применение грубой силы при задержание преступников, но из-за успешной работы на это стараются прикрывать глаза. Основное действие разворачивается, после того, как его напарник Уилсон, внедрённый в банду вьетнамских отморозков, чуть не погиб при очередном преступлении вьетнамцев. В результате в руках полиции оказывается идейный предводитель банды Арчи Син. Банда собирается вызволить своего босса, уничтожив всех свидетелей, включая выжившего Уилсона, но в их планы вмешивается детектив Ма…",
 "f-wd485011": "«Иль Маре» — название домика у моря, где двое влюблённых побывали в разное время. В 1997 году Сон Хён получает странное письмо, в котором говорится, чтобы он остерегался снежной бури, которая пройдёт в 1998 году, причём письмо датировано 1999 годом. Затем мы наблюдаем за историей, произошедшей в прошлом, когда Ын Чжу посылает ему письмо, в котором она просит его найти диктофон, который она потеряла на станции поезда, там, где они встретились впервые.",
 "f-wd56319427": "1973 год. Уругвай находится под военной диктатурой. Одной осенней ночью трое заключенных прямиком из своих камер отправляются на секретную военную операцию, девиз которой — «Если мы не можем их убить, то сведем их с ума». Трое героев оказываются в одиночном заключении на 12 лет. Среди них — Хосе Мухика, будущий президент Уругвая.",
 "f-wd230608": "В далекие и свободные семидесятые, когда на улице бушевала сексуальная революция, жила-была самая «обычная» шведская семья. Жили вместе, дружно, под крышей маленького домика, как и положено настоящим хиппи, разделяя все горести и радости. Семья, надо отметить, была пестрая: горячая сторонница свободной любви Лена и ее сожитель Йоран; застенчивый гомосексуалист Классе и недостижимый объект его мечтаний Лассе; а также Анна, которая еще недавно была замужем за Лассе, но из-за политических соображений решившая стать лесбиянкой. Что и говорить, компания подобралась, что надо! И вот однажды к Йорану переезжает его сестра с двумя детьми, уставшая от выходок грубияна-мужа. Во фривольную, бунтарскую, «семейную» атмосферу вторгается женщина из «нормального» мира. Вот тут-то, все и начинается…",
 "f-wd921612": "История ослепшего музыканта и его любви к добродушной девушке Ингрид.",
 "f-wd196184": "Однажды в Токио стали пропадать люди. Сначала пропал молодой человек, разработавший уникальную компьютерную программу, с помощью которой общение между людьми облегчалось донельзя. Его верные друзья искали его несколько дней, пока одна из его подруг, придя к нему домой, не обнаружила на стене тень парня, в один миг растаявшая как дым, оставив следы какого-то неизвестного вещества.",
 "f-wd14865245": "Валентин вёл жизнь плейбоя в Акапулько, пока бывшая любовница не преступила порог его дома с ребёнком и не вынудила его с девочкой поехать прочь из Мексики.",
 "f-wd653146": "Анна — восемнадцатилетняя художница, живущая со своим отцом в пещере на острове Ибицы. Однажды её талант открывает англичанка Жюстина и предлагает ей переехать в Мадрид, где Анна обнаруживает у себя ещё один дар: она хранит воспоминания разных девушек, живших в разное время, но одинаково умерших в двадцать два года.",
 "f-wd1188348": "Четверо математиков не подозревали о существовании друг друга, пока таинственный незнакомец не собрал их вместе для решения одной трудной головоломки. Хозяин заброшенного дома назвался Ферма, а своим гостям дал имена самых известных в истории математиков. Им предстоит провести два дня в четырёх стенах, которые неожиданно начнут медленно сдвигаться, грозя смертью тем, кто не сумеет разгадать тайну и назвать имя убийцы.",
 "f-wd1659440": "В 1895 году в деревне возле Токио женщина и ее любовник убили мужа-рикшу и бросили тело в старый колодец. Три года они встречались тайком, и ей и другим жителям деревни являлся призрак покойного.  Их разоблачили, и после пыток они были казнены. Все это время их страсть не остывала, и последняя встреча любви состоялась на дне колодца среди останков убитого.",
 "f-wd811007": "Маркос, шофер семьи генерала, и его жена с целью получения выкупа похитили ребенка, который погиб в результате несчастного случая. Герой пытается облегчить свою совесть, сознавшись в содеянном дочери генерала, которая тайком работает в публичном доме. Из жалости она предлагает ему секс, который он принимает за любовь.",
 "f-wd24238125": "Японцы называли этот остров Хасима. Шесть гектаров земли и бетона в 15 километрах от побережья Нагасаки. Здесь с конца XIX века профессиональные шахтеры добывали уголь из подводных забоев. Когда наступила война, и все ушли на фронт, на смену шахтерам стали привозить военнопленных китайцев и корейских переселенцев.  Корейцы называли этот остров Кунхам. Или Остров-Броненосец. Для них он был тюрьмой, из которой невозможно сбежать. Руководитель оркестра Ли Ган-ок поддался на уговоры японского рекрутёра, который обещал бесплатную дорогу и работу в Японии. Так он с малолетней дочерью оказался на Кунхаме в компании соотечественников, среди которых можно было встретить и бандитов, и героев-подпольщиков. И каждый из них был готов принять участие в побеге.",
 "f-wd78730189": "26 октября 1979 года президент Южной Кореи Пак Чон-хи был застрелен директором Национального агентства разведки.",
 "f-wd14551360": "Три девушки в 1980-х в Стокгольме решили создать панк-группу — несмотря на то, что у них не было инструментов, а все вокруг говорили, что панк-рок умер.",
 "f-wd1066446": "Профессор астронавтики Какэру Озоро спасает Луну из-под колес машины. Луна очень благодарна ученому и понимает, что влюбилась в него. Тем временем на Токио обрушивается метель, и на людей нападают демоны, которые ищут кристалл Снежной принцессы Кагуя. Этот самый кристалл находится у профессора Какэру. Камень оказывает негативное влияние на Какэру, и он ссорится со своей девушкой, которая должна полететь в космос с экспедицией из Соединенных Штатов. Луна хочет стать человеком, чтобы как-то помочь Озоро.",
 "f-wd30300951": "Отметив помолвку друзей, девушка отправляется в одиссею по барам ночного Киото. Она встречает пару любителей халявы, попадает на вечеринку сарарименов и даже участвует в конкурсе «кто больше выпьет». А влюблённый в неё парень незаметно преследует девушку в поисках возможности «случайно встретиться». Вокруг них разворачиваются странные события, и в дело вмешиваются различные волшебные существа."
};
